-- Ingredient library expansion, part 2: 34 ingredients.
--
--   solid forms of solutions    glycolic acid crystals, sodium PCA, sorbitol, wheat, rice, oat, keratin and silk proteins (powders),
--                               oat beta-glucan, acetyl hexapeptide-8 (Argireline), hydroxypinacolone retinoate (HPR), green tea extract
--   peptides                    palmitoyl tripeptide-5, acetyl tetrapeptide-5, palmitoyl pentapeptide-4, GHK, carnosine,
--                               hydrolyzed collagen, hydrolyzed pea protein
--   extracts                    ivy, horse chestnut, capsicum, butcher's broom, ginkgo, arnica, guarana, green coffee, bladderwrack,
--                               grape seed, ginger, horsetail, nettle, mulberry root, turmeric
--
-- A solid form keeps the charge, pH window and claim flags of the solution it comes from, and its usage range is scaled by
-- strength (for example 7% glycolic acid crystals is about 10% of the 70% solution). Each says so in its notes, because it is
-- easy to use the same percentage and get a very different result.
--
-- Peptide strengths and recommended doses differ a lot between suppliers. The solutions use the supplier's own dose (for
-- example Eyeseryl at 1-10% of a 0.1% solution); the raw peptide powders are the least certain figures, so their notes
-- point you to the supplier's datasheet. Extract COSMOS status is marked "not compliant" so the claim check asks you to
-- check the supplier's certificate instead of approving it.
--
-- A row is only added when no ingredient with the same INCI name and trade name exists, so this is safe to run more than once.

insert into public.ingredients (id, inci_name, trade_name, function, min_usage_pct, max_usage_pct, cas_number, solubility, ionic_charge, physical_state, optimal_ph_min, optimal_ph_max, max_heating_temp_c, is_vegan, is_cosmos, cost_category, description, common_uses, is_sulfate, is_silicone, is_paraben, is_fragrance, cosmos_compliant, comedogenic_rating, default_min_usage, default_max_usage, notes)
select gen_random_uuid(), 'Glycolic Acid', 'Glycolic Acid (Crystals, 99%)', 'Active (AHA)', 0.7, 7, '79-14-1', 'water', 'non-ionic', 'powder', 3.5, 4.5, 80, true, true, 'low', 'The pure crystalline form of glycolic acid, for chemical exfoliation and cell turnover. The 70% solution is the more common form.', 'Serums, toners, peels', false, false, false, false, true, 0, 1, 5, 'Use about 70% as much as you would of the 70% solution for the same amount of acid (7% crystals equals 10% of the solution). Dissolve it in the water phase. Strongly acidic: wear gloves and eye protection, and keep the pH at 3.5 or higher.'
 where not exists (select 1 from public.ingredients i where lower(i.inci_name) = lower('Glycolic Acid') and lower(i.trade_name) = lower('Glycolic Acid (Crystals, 99%)'));

